// lacak-domba-nearby/index.ts with this repository's firestore.rules on the
// Firestore EMULATOR, synthetic users from the Auth EMULATOR, and a REAL
// local PostgREST + PostgreSQL. Every Firestore read the function makes
// passes the real rules with the caller's own token.
//
// Test seam, in THIS FILE ONLY: the function verifies RS256 tokens against
// Google's keys, which emulator tokens (alg "none") can never pass. Here the
// Google key URL answers with a key generated by the test, which signs
// tokens for the Auth Emulator users, and Firestore REST calls go to the
// emulator. index.ts has no switch for any of this; the last test checks it.
// Needs (LOCAL only): Firebase emulators (auth 9099, firestore 8080) and
//   LD_TEST_SUPABASE_URL, LD_TEST_SERVICE_ROLE_KEY, LD_TEST_DB_URL
// Run: deno test --no-lock --no-config --allow-env --allow-net --allow-read --allow-sys supabase/functions/tests/lacak-domba-emulator_test.ts
import { assert, assertEquals } from "jsr:@std/assert@1";
import { exportJWK, generateKeyPair, SignJWT } from "npm:jose@5.9.6";
import postgres from "npm:postgres@3.4.5";
import {
    adminWrite,
    clearEmulators,
    createUser,
    DOCUMENTS,
    emulatorsRunning,
    loadRules,
    remove,
    PROJECT_ID,
    SERVER_TIME,
    write,
} from "../../../tests/lacak-domba-firebase/emulator.ts";

const GOOGLE_FIRESTORE =
    `https://firestore.googleapis.com/v1/projects/${PROJECT_ID}/databases/(default)/documents`;
const JWKS_URL =
    "https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com";
const SUPABASE_URL = Deno.env.get("LD_TEST_SUPABASE_URL") || "";
const SERVICE_KEY = Deno.env.get("LD_TEST_SERVICE_ROLE_KEY") || "";
const DB_URL = Deno.env.get("LD_TEST_DB_URL") || "";
const isLocal = (url: string) => /^(https?|postgres(ql)?):\/\/([^@/]*@)?(127\.0\.0\.1|localhost)[:/]/.test(url);
const ignore = !(isLocal(SUPABASE_URL) && isLocal(DB_URL) && SERVICE_KEY && await emulatorsRunning());
if (ignore) console.warn("Emulators or local PostgREST/PostgreSQL missing: emulator tests SKIPPED.");

const ORIGIN = "http://localhost:5500";
const ALICE = "test-ld-emu-alice";
const BOB = "test-ld-emu-bob";
const CAROL = "test-ld-emu-carol";
const emulatorTokens: Record<string, string> = {};

// --- tokens: RS256 for Auth Emulator users (test key) -------------------------
const { publicKey, privateKey } = await generateKeyPair("RS256", { extractable: true });
const jwk = { ...(await exportJWK(publicKey)), kid: "emu-kid", alg: "RS256", use: "sig" };
const foreign = await generateKeyPair("RS256", { extractable: true });

async function idToken(
    uid: string,
    options: { expired?: boolean; foreignKey?: boolean; audience?: string } = {},
): Promise<string> {
    const now = Math.floor(Date.now() / 1000);
    return await new SignJWT({})
        .setProtectedHeader({ alg: "RS256", kid: "emu-kid" })
        .setIssuer(`https://securetoken.google.com/${PROJECT_ID}`)
        .setAudience(options.audience || PROJECT_ID)
        .setSubject(uid)
        .setIssuedAt(options.expired ? now - 7200 : now)
        .setExpirationTime(options.expired ? now - 3600 : now + 3600)
        .sign(options.foreignKey ? foreign.privateKey : privateKey);
}

// --- fetch: Google key URL -> test key, Firestore -> emulator -------------------
const realFetch = globalThis.fetch;
const unexpected: string[] = [];
const firestoreStatuses: number[] = [];
globalThis.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = input instanceof Request ? input : new Request(input, init);
    if (request.url === JWKS_URL) return Response.json({ keys: [jwk] });
    if (request.url.startsWith(GOOGLE_FIRESTORE)) {
        const response = await realFetch(
            new Request(DOCUMENTS + request.url.slice(GOOGLE_FIRESTORE.length), request),
        );
        firestoreStatuses.push(response.status);
        return response;
    }
    if (SUPABASE_URL && request.url.startsWith(SUPABASE_URL)) return await realFetch(request);
    unexpected.push(request.url);
    return new Response("blocked by test", { status: 599 });
};

const sql = ignore ? null : postgres(DB_URL, { max: 2, onnotice: () => {} });

Deno.env.set("SUPABASE_URL", SUPABASE_URL || "http://127.0.0.1:1");
Deno.env.set("SUPABASE_SERVICE_ROLE_KEY", SERVICE_KEY || "unset");
let handler: ((request: Request) => Promise<Response>) | null = null;
Object.defineProperty(Deno, "serve", {
    configurable: true,
    writable: true,
    value: (callback: (request: Request) => Promise<Response>) => {
        handler = callback;
        return { finished: Promise.resolve(), shutdown: async () => {} };
    },
});
await import("../lacak-domba-nearby/index.ts");

async function call(
    uid: string | null,
    body: Record<string, unknown>,
    token?: string,
): Promise<{ status: number; data: Record<string, any>; text: string }> {
    const headers: Record<string, string> = { "Content-Type": "application/json", Origin: ORIGIN };
    const bearer = token ?? (uid ? await idToken(uid) : "");
    if (bearer) headers.Authorization = `Bearer ${bearer}`;
    const response = await handler!(new Request("http://edge.test/lacak-domba-nearby", {
        method: "POST",
        headers,
        body: JSON.stringify(body),
    }));
    const text = await response.text();
    return { status: response.status, data: JSON.parse(text), text };
}

// --- what the browser writes, through the rules, with the emulator token -------
async function savePresence(uid: string, discoverable: boolean) {
    const status = await write(`presence/${uid}`, {
        online: true,
        lastSeen: SERVER_TIME,
        updatedAt: SERVER_TIME,
        displayName: `Sintetis ${uid.slice(12)}`,
        photoURL: "",
        komsel: "Komsel Uji",
        wilayah: "Wilayah Uji",
        discoverable,
        showOnline: true,
    }, emulatorTokens[uid]);
    assertEquals(status, 200, `presence write for ${uid}`);
}

async function saveLocation(uid: string, latOffset = 0) {
    const status = await write(
        `presence_locations/${uid}`,
        { latitude: -1 + latOffset, longitude: 131, updatedAt: SERVER_TIME },
        emulatorTokens[uid],
    );
    assertEquals(status, 200, `location write for ${uid}`);
}

async function block(blocker: string, blocked: string) {
    const status = await write(
        `user_blocks/${blocker}/blocked/${blocked}`,
        { blockedUid: blocked, createdAt: SERVER_TIME, displayName: "", photoURL: "" },
        emulatorTokens[blocker],
    );
    assertEquals(status, 200);
}

async function row(uid: string) {
    const [r] = await sql!`
        select discovery_session_id::text as session_id
        from public.lacak_domba_presence where firebase_uid = ${uid}`;
    return r;
}

async function scan(uid: string) {
    await sql!`delete from public.lacak_domba_scan_limits where firebase_uid = ${uid}`;
    return await call(uid, { action: "scan", radiusKm: 5 });
}

const listed = (data: Record<string, any>, uid: string) =>
    (data.results || []).some((member: { uid: string }) => member.uid === uid);

const test = (name: string, fn: () => Promise<void>) =>
    Deno.test({
        name,
        ignore,
        sanitizeOps: false,
        sanitizeResources: false,
        fn: async () => {
            await clearEmulators();
            await loadRules();
            await sql!`delete from public.lacak_domba_presence where firebase_uid like 'test-ld-emu-%'`;
            await sql!`delete from public.lacak_domba_blocks where blocker_uid like 'test-ld-emu-%'`;
            await sql!`delete from public.lacak_domba_scan_limits where firebase_uid like 'test-ld-emu-%'`;
            firestoreStatuses.length = 0;
            for (const uid of [ALICE, BOB, CAROL]) {
                emulatorTokens[uid] = (await createUser(uid)).emulatorToken;
                // Activation is an administrator action (rules bypassed here).
                await adminWrite(`users/${uid}`, { uid, nama: "Sintetis", status_akun: "Aktif" });
            }
            await fn();
        },
    });

// --- tests ------------------------------------------------------------------

test("two accounts: real rules allow every read the function makes; ranges only, no coordinates", async () => {
    await savePresence(ALICE, true);
    await saveLocation(ALICE);
    const start = await call(ALICE, { action: "discovery_start" });
    assertEquals(start.status, 200, start.text);
    assertEquals(start.data.discovery.active, true);
    await savePresence(BOB, false);
    await saveLocation(BOB, 0.001);
    const result = await scan(BOB);
    assertEquals(result.status, 200, result.text);
    assert(listed(result.data, ALICE), "Bob finds Alice");
    assert(!/latitude|longitude|"lat"|"lng"|131\.0|-1\.0/.test(result.text), "no coordinates in the reply");
    assertEquals(result.data.results[0].distanceRange, "< 1 KM");
    assert(firestoreStatuses.length > 0 && firestoreStatuses.every((s) => s === 200 || s === 404),
        `a Firestore read was refused by the rules: ${firestoreStatuses}`);
});

test("account status: pending and deactivated accounts are refused and hidden", async () => {
    await adminWrite(`users/${CAROL}`, { uid: CAROL, nama: "Sintetis", status_akun: "Menunggu Verifikasi" });
    await savePresence(CAROL, true);
    await saveLocation(CAROL);
    const pending = await call(CAROL, { action: "discovery_start" });
    assertEquals(pending.status, 403);
    assertEquals(pending.data.error, "account_not_active");
    assertEquals(await row(CAROL), undefined);

    await savePresence(ALICE, true);
    await saveLocation(ALICE);
    assertEquals((await call(ALICE, { action: "discovery_start" })).status, 200);
    await adminWrite(`users/${ALICE}`, { uid: ALICE, nama: "Sintetis", status_akun: "Nonaktif" });
    const sync = await call(ALICE, { action: "sync" });
    assertEquals(sync.status, 403);
    assertEquals(await row(ALICE), undefined, "a deactivated account is removed at once");
});

// A block lives in the BLOCKER's Firestore list, which only the blocker's
// token can read. The server copy (lacak_domba_blocks) is refreshed by the
// blocker's own requests only: every sync (whatever syncBlocks says), a
// scan, discovery_start and discovery_extend. Each step below checks the
// state BEFORE and AFTER the request that is supposed to apply it, and that
// the other user's scan never applies it as a side effect.
const mirrored = async (blocker: string) =>
    (await sql!`select blocked_uid from public.lacak_domba_blocks where blocker_uid = ${blocker} order by 1`)
        .map((r) => r.blocked_uid);

test("blocks written through the rules (as kontak.html does): before/after the blocker's sync, both directions, unblock", async () => {
    await savePresence(ALICE, true);
    await saveLocation(ALICE);
    assertEquals((await call(ALICE, { action: "discovery_start" })).status, 200);
    await savePresence(BOB, false);
    await saveLocation(BOB, 0.001);
    assert(listed((await scan(BOB)).data, ALICE), "visible without blocks");

    // Alice blocks Bob on another page while her session runs.
    await block(ALICE, BOB);
    assertEquals(await mirrored(ALICE), [], "BEFORE: not mirrored yet");
    assert(listed((await scan(BOB)).data, ALICE), "BEFORE: Bob still finds Alice (the window)");
    assertEquals(await mirrored(ALICE), [], "Bob's scan did not apply Alice's block");
    // What visibilitychange sends: syncBlocks false. The server re-reads anyway.
    assertEquals((await call(ALICE, { action: "sync", syncBlocks: false })).status, 200);
    assertEquals(await mirrored(ALICE), [BOB], "AFTER: mirrored by Alice's sync");
    assert(!listed((await scan(BOB)).data, ALICE), "AFTER: hidden");

    // Unblock: hidden until Alice's next sync, visible after it.
    assertEquals(await remove(`user_blocks/${ALICE}/blocked/${BOB}`, emulatorTokens[ALICE]), 200);
    assert(!listed((await scan(BOB)).data, ALICE), "BEFORE unblock sync: still hidden (safe side)");
    await call(ALICE, { action: "sync", syncBlocks: false });
    assertEquals(await mirrored(ALICE), []);
    assert(listed((await scan(BOB)).data, ALICE), "AFTER unblock sync: visible again");

    // A restart and an extend re-read the list.
    await block(ALICE, BOB);
    await call(ALICE, { action: "clear", mode: "stop" });
    await sql!`delete from public.lacak_domba_blocks where blocker_uid = ${ALICE}`;
    const restarted = await call(ALICE, { action: "discovery_start" });
    assertEquals(await mirrored(ALICE), [BOB], "discovery_start mirrored it");
    await sql!`delete from public.lacak_domba_blocks where blocker_uid = ${ALICE}`;
    await saveLocation(ALICE);
    const extended = await call(ALICE, { action: "discovery_extend", sessionId: restarted.data.discovery.sessionId });
    assertEquals(extended.status, 200, extended.text);
    assertEquals(await mirrored(ALICE), [BOB], "discovery_extend mirrored it");
    assert(!listed((await scan(BOB)).data, ALICE));
    await remove(`user_blocks/${ALICE}/blocked/${BOB}`, emulatorTokens[ALICE]);
    await call(ALICE, { action: "sync" });

    // Other direction: Bob blocks Alice; his own scan applies it at once.
    assert(listed((await scan(BOB)).data, ALICE), "visible again");
    await block(BOB, ALICE);
    assertEquals(await mirrored(BOB), [], "BEFORE Bob's request");
    assert(!listed((await scan(BOB)).data, ALICE), "Bob's scan applied his block");
    assertEquals(await mirrored(BOB), [ALICE]);
    await savePresence(BOB, true);
    await call(BOB, { action: "discovery_start" });
    assert(!listed((await scan(ALICE)).data, BOB), "Alice cannot find Bob, who blocked her");
});

test("a blocked user cannot remove or read the blocker's list, through the rules or the function", async () => {
    await savePresence(ALICE, true);
    await saveLocation(ALICE);
    await call(ALICE, { action: "discovery_start" });
    await block(ALICE, BOB);
    await call(ALICE, { action: "sync" });
    assertEquals(await remove(`user_blocks/${ALICE}/blocked/${BOB}`, emulatorTokens[BOB]), 403, "rules refuse");
    // Bob's requests only ever replace HIS OWN mirrored list.
    await savePresence(BOB, false);
    await saveLocation(BOB, 0.001);
    await call(BOB, { action: "sync", uid: ALICE, firebase_uid: ALICE });
    assertEquals(await mirrored(ALICE), [BOB], "Alice's mirror untouched by Bob");
    assert(!listed((await scan(BOB)).data, ALICE));
});

test("another user's uid or session in the body changes nothing for that user", async () => {
    await savePresence(ALICE, true);
    await saveLocation(ALICE);
    const start = await call(ALICE, { action: "discovery_start" });
    const aliceSession = start.data.discovery.sessionId;
    await savePresence(BOB, false);
    await saveLocation(BOB, 0.001);
    const spoof = { uid: ALICE, firebase_uid: ALICE, p_uid: ALICE };
    assertEquals((await call(BOB, { action: "clear", mode: "stop", ...spoof })).status, 200);
    assertEquals((await call(BOB, { action: "clear", mode: "leave", sessionId: aliceSession, ...spoof })).status, 200);
    const extend = await call(BOB, { action: "discovery_extend", sessionId: aliceSession, ...spoof });
    assertEquals(extend.status, 412, "Bob is not discoverable, so he has nothing to extend");
    assertEquals((await row(ALICE))?.session_id, aliceSession, "Alice's session is untouched");
    assertEquals(await row(BOB), undefined);
});

test("tokens: Auth Emulator (alg none), foreign key, expired, other project and none are refused", async () => {
    await savePresence(ALICE, true);
    await saveLocation(ALICE);
    const cases: Array<[string, string]> = [
        ["auth emulator token", emulatorTokens[ALICE]],
        ["foreign key", await idToken(ALICE, { foreignKey: true })],
        ["expired", await idToken(ALICE, { expired: true })],
        ["other project", await idToken(ALICE, { audience: "other-project" })],
        ["garbage", "not.a.token"],
    ];
    for (const [label, token] of cases) {
        const result = await call(null, { action: "discovery_start" }, token);
        assertEquals(result.status, 401, label);
    }
    assertEquals((await call(null, { action: "discovery_start" })).status, 401, "no token");
    assertEquals(await row(ALICE), undefined);
});

test("the seam exists only in tests: index.ts has no emulator, host or key override", async () => {
    const source = await Deno.readTextFile(new URL("../lacak-domba-nearby/index.ts", import.meta.url));
    const envReads = [...source.matchAll(/Deno\.env\.get\(\s*"([^"]+)"\s*\)/g)].map((m) => m[1]).sort();
    assertEquals(envReads, ["SUPABASE_SERVICE_ROLE_KEY", "SUPABASE_URL"]);
    // 127.0.0.1:5500 / localhost:5500 are allowed CORS origins, not hosts.
    for (const forbidden of [/EMULATOR/i, /127\.0\.0\.1(?!:5500)/, /localhost(?!:5500)/, /alg\s*:\s*["']none/i, /createLocalJWKSet/, /decodeJwt/]) {
        assert(!forbidden.test(source), `index.ts contains ${forbidden}`);
    }
    assert(source.includes('algorithms: ["RS256"]'));
    assert(source.includes("https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com"));
    assert(source.includes("https://securetoken.google.com/${PROJECT_ID}"));
    // The tests directory is not a function: nothing in it can be deployed.
    for (const name of ["index.ts", "index.js"]) {
        const exists = await Deno.stat(new URL(`./${name}`, import.meta.url)).then(() => true, () => false);
        assert(!exists, `supabase/functions/tests/${name} would make the tests deployable`);
    }
    assertEquals(unexpected, [], "a request left the machine");
});

Deno.test({
    name: "teardown",
    ignore,
    sanitizeOps: false,
    sanitizeResources: false,
    fn: async () => {
        await clearEmulators();
        await sql!`delete from public.lacak_domba_presence where firebase_uid like 'test-ld-emu-%'`;
        await sql!`delete from public.lacak_domba_blocks where blocker_uid like 'test-ld-emu-%'`;
        await sql!`delete from public.lacak_domba_scan_limits where firebase_uid like 'test-ld-emu-%'`;
        await sql!.end();
    },
});
